[ExtensionOf(FormStr(SalesCreateQuotation))]
final class AVASalesCreateQuotationFrm_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    next init();

    this.avaSetTabAndFocus();
}

/// <summary>
///     AVA <c>run</c> method.
/// </summary>
void run()
{
    this.avaSetTabAndFocus();

    next run();

    if (isConfigurationkeyEnabled(configurationKeyNum(TradeCustomerSearch)))
    {
        this.avaSetTabAndFocus();
    }
}

/// <summary>
///    AVA <c>avaSetTabAndFocus</c> method.
/// </summary>
public void avaSetTabAndFocus()
{
    FormTabPageControl          locFormTabPageControl;
    FormCommandButtonControl    locFormCommandButtonControl;

    locFormCommandButtonControl  = this.design().controlName(formControlStr(SalesCreateQuotation, Cancel)) as FormCommandButtonControl;
    locFormCommandButtonControl.setFocus();

    locFormTabPageControl = this.design().controlName(formControlStr(SalesCreateQuotation, TabCustomerAndAddress)) as FormTabPageControl;
    locFormTabPageControl.fastTabExpanded(0); // Auto
    locFormTabPageControl.collapse();
}
